library(transDIF); for (s in c(9, 1:6)) { sim <- td_simulate(n_ref = 1500, n_focal = 200, n_items = 40, seed = s); tr <- sim$truth; cal <- td_calibrate(sim$responses, sim$group); dif <- td_dif(cal); it <- cal$items; e_eb <- dif$items$dif_mean - tr$dif; e_raw <- it$d - dif$link[["c"]] - tr$dif; cat(s, "rmse eb", round(sqrt(mean(e_eb^2)),3), "raw", round(sqrt(mean(e_raw^2)),3), "| DIF items: eb", round(sqrt(mean(e_eb[tr$dif_item]^2)),3), "raw", round(sqrt(mean(e_raw[tr$dif_item]^2)),3), "| null: eb", round(sqrt(mean(e_eb[!tr$dif_item]^2)),3), "raw", round(sqrt(mean(e_raw[!tr$dif_item]^2)),3), "| pi0", round(dif$link[["pi0"]],2), "tau1", round(dif$link[["tau1"]],2), "m1", round(dif$link[["m1"]],2), "\n") }
